import os
import re
import sys
import copy
from glob import glob

from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

def norm(v):
    if v is None:
        return ""
    s = str(v).strip().lower()
    return re.sub(r"[^a-z0-9 ]", " ", s)

def find_target():
    if os.path.exists("sales_data.xlsx"):
        return "sales_data.xlsx"
    xs = [p for p in glob("*.xlsx") if not p.startswith("~$")]
    if not xs:
        raise SystemExit("No .xlsx workbook found in working directory.")
    return sorted(xs)[0]

def main():
    path = sys.argv[1] if len(sys.argv) > 1 and sys.argv[1].endswith(".xlsx") else find_target()
    wb = load_workbook(path)
    print("Workbook:", path)
    print("Sheets:", wb.sheetnames)

    target_ws = None
    for ws in wb.worksheets:
        hr = None
        for r in range(1, min(ws.max_row, 10) + 1):
            if any(ws.cell(row=r, column=c).value is not None for c in range(1, ws.max_column + 1)):
                hr = r
                break
        if hr is None:
            continue
        norm_headers = {}
        for c in range(1, ws.max_column + 1):
            h = ws.cell(row=hr, column=c).value
            if h is not None:
                norm_headers[c] = norm(h)
        has_rev = any("revenue" in n or n in ("sales", "total sales", "sales amount", "net sales", "amount", "turnover") or ("sales" in n and not any(k in n for k in ("person", " rep", "team", "region", "date"))) for n in norm_headers.values())
        has_prof = any("profit" in n for n in norm_headers.values())
        if has_rev and has_prof:
            target_ws = ws
            break
    if target_ws is None:
        raise SystemExit("Could not locate a sheet with revenue/sales and profit columns.")

    ws = target_ws
    hr = None
    for r in range(1, min(ws.max_row, 10) + 1):
        if any(ws.cell(row=r, column=c).value is not None for c in range(1, ws.max_column + 1)):
            hr = r
            break

    headers = {}
    for c in range(1, ws.max_column + 1):
        h = ws.cell(row=hr, column=c).value
        if h is not None:
            headers[c] = (str(h).strip(), norm(h))
    print("Sheet:", ws.title, "header row:", hr)
    print("Headers:", [(c, h[0]) for c, h in headers.items()])

    def pick(match):
        for c, (_, n) in headers.items():
            if match(n):
                return c
        return None

    rev_col = pick(lambda n: "revenue" in n or n in ("sales", "total sales", "sales amount", "net sales", "amount", "turnover") or ("sales" in n and not any(k in n for k in ("person", " rep", "team", "region", "date"))))
    prof_col = pick(lambda n: "profit" in n and "margin" not in n)
    cost_col = pick(lambda n: "cost" in n or "cogs" in n or "expense" in n)

    if rev_col is None:
        raise SystemExit("No revenue/sales column found to base the margin on.")
    if prof_col is None and cost_col is None:
        raise SystemExit("No profit or cost column found to compute the margin.")

    margin_col = pick(lambda n: "margin" in n)
    append_new = margin_col is None
    new_col = (ws.max_column + 1) if append_new else margin_col

    last = ws.max_row
    while last > hr:
        if any(ws.cell(row=last, column=c).value is not None for c in range(1, ws.max_column + 1)):
            break
        last -= 1
    if last <= hr:
        raise SystemExit("No data rows found beneath the header.")

    if append_new:
        for r in range(hr, last + 1):
            if ws.cell(row=r, column=new_col).value is not None:
                raise SystemExit("Proposed new column %s is not empty; aborting without changes." % get_column_letter(new_col))
        header_text = "Profit Margin (%)"
    else:
        header_text = ws.cell(row=hr, column=new_col).value

    denominator = rev_col
    if prof_col is not None:
        numerator = prof_col
    else:
        numerator = rev_col
        denom_src = cost_col
        # margin = (revenue - cost) / revenue

    count = 0
    for r in range(hr + 1, last + 1):
        if append_new and ws.cell(row=r, column=rev_col).value is None and ws.cell(row=r, column=(prof_col or cost_col)).value is None:
            continue
        if prof_col is not None:
            f = "=IFERROR(%s%d/%s%d,0)" % (get_column_letter(prof_col), r, get_column_letter(rev_col), r)
        else:
            f = "=IFERROR((%s%d-%s%d)/%s%d,0)" % (get_column_letter(rev_col), r, get_column_letter(cost_col), r, get_column_letter(rev_col), r)
        cell = ws.cell(row=r, column=new_col)
        cell.value = f
        cell.number_format = "0.0%"
        count += 1

    hcell = ws.cell(row=hr, column=new_col)
    hcell.value = header_text
    hcell.number_format = "0.0%"
    src_h = hr if new_col > 1 else None
    if src_h is not None:
        try:
            ref = ws.cell(row=hr, column=new_col - 1)
            if ref.font is not None:
                hcell.font = copy.copy(ref.font)
            if ref.fill is not None and ref.fill.fill_type is not None:
                hcell.fill = copy.copy(ref.fill)
            if ref.alignment is not None:
                hcell.alignment = copy.copy(ref.alignment)
            if ref.border is not None:
                hcell.border = copy.copy(ref.border)
        except Exception as e:
            print("Note: style copy skipped:", e)

    if append_new:
        wd = ws.column_dimensions.get(get_column_letter(rev_col))
        if wd is not None and wd.width:
            ws.column_dimensions[get_column_letter(new_col)].width = wd.width

    wb.save(path)
    print("Appended header '%s' at column %s (%s)" % (header_text, get_column_letter(new_col), new_col))
    print("Rows populated with formulas:", count)
    sample = ws.cell(row=hr + 1, column=new_col).value if count else None
    print("Sample formula:", sample)

if __name__ == "__main__":
    main()

